import glob
import os
import re
import csv
from datetime import date, timedelta

ref = date(2025, 8, 12)
periods = {
    'today': (ref, ref),
    'last_7_days': (ref - timedelta(days=6), ref),
    'last_30_days': (ref - timedelta(days=29), ref),
    'month_to_date': (date(ref.year, ref.month, 1), ref),
}
severities = ['ERROR', 'WARNING', 'INFO']
counts = {p: {s: 0 for s in severities} for p in periods}
counts['total'] = {s: 0 for s in severities}

sev_re = re.compile(r'\[(ERROR|WARNING|INFO)\]')

for path in glob.glob('/app/logs/*.log'):
    fname = os.path.basename(path)
    try:
        file_date = date.fromisoformat(fname.split('_')[0])
    except Exception:
        continue
    with open(path, 'r', encoding='utf-8', errors='ignore') as f:
        for line in f:
            m = sev_re.search(line)
            if not m:
                continue
            sev = m.group(1)
            counts['total'][sev] += 1
            for p, (start, end) in periods.items():
                if start <= file_date <= end:
                    counts[p][sev] += 1

with open('/app/summary.csv', 'w', newline='') as out:
    writer = csv.writer(out)
    writer.writerow(['period', 'severity', 'count'])
    for p in ['today', 'last_7_days', 'last_30_days', 'month_to_date', 'total']:
        for s in severities:
            writer.writerow([p, s, counts[p][s]])
